// Measured against @anthropic-ai/claude-agent-sdk 0.3.233, the version Skill Hub
// pins. Four conditions decide whether the Skill is loaded and every one of them
// fails silently: a run that loaded zero Skills still answers plausibly and still
// reports success.
//   1. cwd is the directory that holds .claude/skills/ - not where this file is.
//   2. settingSources (setting_sources in the Python package) is OMITTED. On
//      0.3.233 passing ["project"] discovered no project Skill at all, while
//      leaving the option out discovered it. That is the reverse of 0.2.137 and
//      of how the documentation reads, so treat it as bound to this version.
//   3. skills: "all" - 0.3.x moved Skill enablement out of allowedTools, where
//      passing "Skill" is deprecated.
//   4. allowedTools still has to name the tools the Skill's own steps use.
import { query } from "@anthropic-ai/claude-agent-sdk";

for await (const message of query({
  prompt: "List the skills you can use, and say whether <name> is among them.",
  options: {
    cwd: "./workdir",
    skills: "all",
    allowedTools: ["Skill", "Read", "Write", "Bash"],
  },
})) {
  console.log(message);
}
